// checkpointRemoteIsInherited reports whether the configured checkpoint_remote
// looks like it belongs to an upstream project rather than to this developer,
// along with a short reason for logging.
//
// checkpoint_remote is normally committed in .entire/settings.json, so anyone who
// forks or clones the project inherits it. Honoring it blindly would push a
// contributor's session data into the upstream project's checkpoint repo — which
// they typically cannot write to and should not be writing to. This is the check
// that guards against that (added in e8b589835 as "fork detection").
//
// Ownership is decided from two local signals, no network:
//
//  1. A checkpoint_remote in .entire/settings.local.json is gitignored and
//     per-clone, so it cannot have been inherited — it is always ours.
//  2. Otherwise, compare the CHECKPOINT repo's owner against ORIGIN's owner:
//     "am I working in a repo owned by whoever owns the checkpoint repo?" A fork
//     clone has origin <fork>/app against a checkpoint repo owned by upstream,
//     and mismatches.
//
// Deliberately NOT keyed on the push remote. The predecessor compared the push
// destination's owner, which conflates "is this setting mine" with "where is this
// particular push going" — so pushing to any differently-owned remote (a backup,
// a colleague's fork) disabled the user's own checkpoint_remote and sent
// checkpoints to that remote instead. It also cannot be expressed at all for a
// remote carrying several push URLs with different owners, since one boolean has
// to cover the whole set.
//
// An origin whose owner cannot be determined (absent remote, non-forge URL such
// as a bare local path) counts as inherited: for a committed setting we cannot
// confirm ownership, and falling back preserves the previous behavior for those
// repos. The settings.local.json signal is the escape hatch when the checkpoint
// repo is genuinely ours but owned by a different account or org than origin.
func checkpointRemoteIsInherited(ctx context.Context, config *settings.CheckpointRemoteConfig, originURL string) (bool, string) {
	checkpointOwner := config.Owner()
	if checkpointOwner == "" {
		// No owner to compare (malformed repo field). Matches the predecessor,
		// which skipped the check rather than blocking on it.
		return false, ""
	}
	if settings.CheckpointRemoteIsLocalOnly(ctx) {
		return false, ""
	}
	if originURL == "" {
		return true, "no origin remote to establish ownership"
	}
	info, err := ParseURL(originURL)
	if err != nil || info.Owner == "" {
		return true, "origin URL owner could not be determined"
	}
	if strings.EqualFold(info.Owner, checkpointOwner) {
		return false, ""
	}
	return true, fmt.Sprintf("origin owner %q differs from checkpoint owner %q", info.Owner, checkpointOwner)
}

// GetPushURL returns the URL a push to remoteName delivers to. A remote's push
// destination is remote.<name>.pushurl when set and only otherwise its url, so
// reading the plain url (as GetRemoteURL does) can name a different repository
// than the one being pushed to. Where several push URLs are configured this
// returns the first; callers needing the full set use GetPushURLs.
func GetPushURL(ctx context.Context, remoteName string) (string, error) {
	urls, err := gitremote.GetPushURLs(ctx, remoteName)
	if err != nil {
		return "", fmt.Errorf("get push URL: %w", err)
	}
	return urls[0], nil
}

// GetPushURLs returns every URL a push to remoteName delivers to, in config order.

// GetPushURLs returns every URL a push to remoteName delivers to, in config
// order. A remote's push destinations are remote.<name>.pushurl when any is set
// and its remote.<name>.url otherwise — and BOTH may repeat, in which case git
// pushes to all of them. So this, not GetRemoteURL, describes where a push
// actually goes; GetRemoteURL reports the fetch URL, which can name a different
// repository. Returns at least one entry on success.
func GetPushURLs(ctx context.Context, remoteName string) ([]string, error) {
	cmd := exec.CommandContext(ctx, "git", "remote", "get-url", "--push", "--all", remoteName)
	output, err := cmd.Output()
	if err != nil {
		return nil, fmt.Errorf("remote %q not found", remoteName)
	}
	var urls []string
	for _, line := range strings.Split(string(output), "\n") {
		if trimmed := strings.TrimSpace(line); trimmed != "" {
			urls = append(urls, trimmed)
		}
	}
	if len(urls) == 0 {
		return nil, fmt.Errorf("remote %q has no push URL", remoteName)
	}
	return urls, nil
}

