// Spawns many subprocesses concurrently from a multithreaded Go process.
// Nothing here is specific to the entire CLI: the child is /usr/bin/true.
func storm(t *testing.T, attr *syscall.SysProcAttr) {
	const workers, each = 24, 40
	var wg sync.WaitGroup
	var mu sync.Mutex
	fails := 0
	for i := 0; i < workers; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for j := 0; j < each; j++ {
				cmd := exec.Command("/usr/bin/true")
				cmd.SysProcAttr = attr
				if out, err := cmd.CombinedOutput(); err != nil {
					mu.Lock()
					fails++
					mu.Unlock()
					t.Errorf("spawn failed: %v out=%q", err, out)
					return
				}
			}
		}()
	}
	wg.Wait()
	if fails > 0 {
		t.Logf("%d/%d spawns failed", fails, workers*each)
	}
}

